package br.com.brindespro.quote;
import jakarta.persistence.*;import java.math.BigDecimal;
@Entity @Table(name="quote_items") public class QuoteItem { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id;@ManyToOne(optional=false) @JoinColumn(name="quote_id") public Quote quote;@Column(name="product_id") public Long productId;@Column(name="variant_id") public Long variantId;@Column(name="kit_id") public Long kitId;@Column(name="product_name",nullable=false) public String productName;@Column(nullable=false) public String color;@Column(nullable=false) public String material;@Column(nullable=false) public int quantity;@Column(nullable=false) public String engraving;@Column(name="printing_position",nullable=false) public String printingPosition;@Column(nullable=false) public String deadline;@Column(name="base_unit_price",nullable=false,precision=12,scale=2) public BigDecimal baseUnitPrice;@Column(name="unit_price",nullable=false,precision=12,scale=2) public BigDecimal unitPrice;@Column(nullable=false,precision=12,scale=2) public BigDecimal surcharge;@Column(name="line_total",nullable=false,precision=14,scale=2) public BigDecimal lineTotal;@Column(name="logo_file_id") public Long logoFileId;@Column(name="preview_x",precision=6,scale=2) public BigDecimal previewX;@Column(name="preview_y",precision=6,scale=2) public BigDecimal previewY;@Column(name="preview_scale",precision=6,scale=2) public BigDecimal previewScale;protected QuoteItem(){} public QuoteItem(Quote quote){this.quote=quote;} }
